"""Write the generated part of the TypeScript SDK (`typescript/src/generated/`)."""

from __future__ import annotations

import json
import re
import textwrap
from pathlib import Path

from model import Api, Field, Node, Param, Route, TypeRef, camel, param_literals, pascal

HEADER = """// This file is generated by codegen/generate.py from spec/openapi.json.
// Do not edit it by hand: change the generator or the overrides, then run `make generate`.
/* eslint-disable */
"""

IDENT = re.compile(r"^[A-Za-z_$][A-Za-z0-9_$]*$")
TIME_DOC = {
    "since_ms": "Lower time bound, inclusive.",
    "until_ms": "Upper time bound, inclusive to the millisecond.",
    "before_ms": "Upper time bound, exclusive (rows strictly before it). Not combinable with `until`.",
}


def key(name: str) -> str:
    return name if IDENT.match(name) else json.dumps(name)


def jsdoc(text: str, indent: int = 0, width: int = 96) -> list[str]:
    text = text.strip().replace("*/", "*\\/")
    if not text:
        return []
    pad = " " * indent
    lines = [pad + "/**"]
    for para in text.split("\n"):
        para = para.rstrip()
        if not para:
            lines.append(pad + " *")
            continue
        for ln in textwrap.wrap(para, width - indent - 3, break_long_words=False, break_on_hyphens=False) or [""]:
            lines.append(f"{pad} * {ln}")
    while lines[-1].endswith(" *"):
        lines.pop()
    lines.append(pad + " */")
    return lines


def ts_type(t: TypeRef) -> str:
    if t.kind == "str":
        s = "string"
    elif t.kind in ("int", "float"):
        s = "number"
    elif t.kind == "bool":
        s = "boolean"
    elif t.kind == "datetime":
        s = "Date"
    elif t.kind == "date":
        s = "string"
    elif t.kind == "literal":
        s = t.name or " | ".join(json.dumps(v) for v in t.values)
    elif t.kind == "model":
        s = t.name or "unknown"
    elif t.kind == "list":
        inner = ts_type(t.item) if t.item else "unknown"
        s = f"Array<{inner}>"
    elif t.kind == "dict":
        s = "Record<string, unknown>"
    elif t.kind == "union":
        s = " | ".join(ts_type(o) for o in t.options)
    else:
        return "unknown"
    return f"{s} | null" if t.nullable else s


# --------------------------------------------------------------------------- models


def emit_models(api: Api) -> str:
    out = [HEADER, "/** Typed rows returned by the API. Field names are the API's, so the docs read the same. */", ""]
    lits = sorted({f.type.name for m in api.models.values() for f in m.fields if f.type.kind == "literal" and f.type.name})
    if lits:
        out.append(f"import type {{ {', '.join(lits)} }} from './literals.js';")
        out.append("")
    for m in api.models.values():
        routes = [r.path for r in api.routes if r.model == m.name]
        head = f"Row of `{'`, `'.join(routes)}`." if routes else (m.description or f"Nested object ({m.name}).")
        out.extend(jsdoc(head))
        out.append(f"export interface {m.name} {{")
        for f in m.fields:
            desc = f.description + (f" Unit: {f.unit}." if f.unit else "")
            out.extend(jsdoc(desc, 2))
            opt = "" if f.required else "?"
            out.append(f"  {key(f.name)}{opt}: {ts_type(f.type)};")
        out.append("  /** Fields added by the API after this SDK was released. */")
        out.append("  [extra: string]: unknown;")
        out.append("}")
        out.append("")
    # date descriptors: which keys to turn into Date, which nested models to walk
    out.append("/** @internal Which fields of each model are ISO date-times, and which hold nested models. */")
    out.append("export const MODEL_SHAPES: Record<string, { dates: string[]; nested: Record<string, string> }> = {")
    for m in api.models.values():
        dates = [f.name for f in m.fields if f.type.kind == "datetime"]
        nested = {}
        for f in m.fields:
            t = f.type.item if f.type.kind == "list" and f.type.item else f.type
            if t.kind == "model" and t.name:
                nested[f.name] = t.name
        out.append(f"  {m.name}: {{ dates: {json.dumps(dates)}, nested: {json.dumps(nested)} }},")
    out.append("};")
    return "\n".join(out) + "\n"


def emit_literals(api: Api) -> str:
    out = [HEADER, "/** Closed sets of values accepted by the API. */", ""]
    for lit in api.literals.values():
        out.extend(jsdoc(lit.description))
        out.append(f"export type {lit.name} = {' | '.join(json.dumps(v) for v in lit.values)};")
        out.append(f"export const {lit.name}Values = {json.dumps(list(lit.values))} as const;")
        out.append("")
    out.append("/** The technical indicators served by `POST /v1/indicators`. */")
    out.append(f"export type IndicatorType = {' | '.join(json.dumps(t) for t in sorted(api.indicators))};")
    out.append("")
    out.append("/** Stable machine-readable `error.code` values. Branch on them, never on the message. */")
    out.append(f"export type ErrorCode = {' | '.join(json.dumps(c) for c in api.error_codes)};")
    return "\n".join(out) + "\n"


# --------------------------------------------------------------------------- resources


def type_name(node: Node) -> str:
    return "".join(pascal(s) for s in node.path)


def prop(seg: str) -> str:
    return camel(seg)


def param_ts(p: Param) -> str:
    if p.time:
        return "TimeLike"
    if p.wire == "fields":
        return "Fields"
    return ts_type(p.type)


def param_doc(p: Param) -> str:
    if p.time:
        return TIME_DOC[p.wire] + " A `Date`, an ISO string (`2026-01-01`) or epoch milliseconds."
    if p.wire == "fields":
        return "Only return these fields of each row (array or comma-separated). Rows are then partial."
    d = p.description
    if p.default is not None and "default" not in d.lower():
        d += f" Default: `{p.default}`."
    return d


def emit_params(name: str, params: list[Param], out: list[str], exclude: set[str] = frozenset()) -> bool:
    """Emit `interface <name>`; returns whether any field is required."""
    out.append(f"export interface {name} {{")
    required = False
    for p in params:
        if p.wire in exclude:
            continue
        out.extend(jsdoc(param_doc(p), 2))
        opt = "" if p.required else "?"
        required = required or p.required
        out.append(f"  {key(p.name)}{opt}: {param_ts(p)};")
    out.append("}")
    out.append("")
    return required


def return_ts(r: Route) -> str:
    if r.shape == "list":
        return f"Array<M.{r.model}>" if r.model else "Array<unknown>"
    if r.shape == "object":
        return f"M.{r.model} | null" if r.model else "unknown"
    return "unknown"


def route_const(r: Route) -> str:
    limit = next((p for p in r.params if p.wire == "limit"), None)
    spec = {
        "path": r.path,
        "method": r.method,
        "shape": r.shape,
        "model": r.model,
        "paginated": r.paginated,
        "pathParams": [p.wire for p in r.params if p.location == "path"],
        "maxLimit": int(limit.maximum) if limit and limit.maximum else None,
        "rangeMode": "after_id" in {p.wire for p in r.params},
        "wire": {p.name: p.wire for p in r.params if p.name != p.wire},
    }
    return json.dumps(spec)


def emit_snapshot(api: Api, r: Route, out: list[str]) -> None:
    singles = [f for f in api.snapshot_fields if not f.timeframe]
    multis: dict[str, list[str]] = {}
    for f in api.snapshot_fields:
        if f.timeframe:
            multis.setdefault(f.base, []).append(f.timeframe)
    out.append("/** A snapshot depth: `true` for the latest value, `N` for the N latest rows. */")
    out.append("export type Depth = boolean | number;")
    out.append("")
    out.append("export interface SnapshotParams {")
    out.append("  /** Trading pair, e.g. `BTCUSDT`. */")
    out.append("  symbol: string;")
    for f in singles:
        out.extend(jsdoc(f.description, 2))
        # Depth 1 only: `true` (or 1).
        out.append(f"  {f.base}?: {'true | 1' if f.maximum == 1 else 'Depth'};")
    for base, tfs in multis.items():
        lit = "KlineTimeframe" if "1w" in tfs else "Timeframe"
        out.append(f"  /** `{base}` per timeframe: `{{ \"1h\": 24 }}` = the 24 latest `{base}@1h` rows. */")
        out.append(f"  {base}?: Partial<Record<{lit}, Depth>>;")
    out.append("}")
    out.append("")
    out.append("/** The payload of `GET /v1/snapshot`: the requested fields, typed like their routes. */")
    out.append("export interface SnapshotData {")
    for f in api.snapshot_fields:
        # A field limited to depth 1 is its route's OBJECT (or null), never an array.
        if f.model and f.maximum == 1:
            t = f"M.{f.model} | null"
        else:
            t = f"M.{f.model} | Array<M.{f.model}> | null" if f.model else "unknown"
        out.append(f"  {key(f.wire)}?: {t};")
    out.append("  [extra: string]: unknown;")
    out.append("}")
    out.append("")
    out.append("export const SNAPSHOT_FIELDS: Record<string, { base: string; timeframe: string | null; model: string | null }> = {")
    for f in api.snapshot_fields:
        out.append(f"  {json.dumps(f.wire)}: {{ base: {json.dumps(f.base)}, timeframe: {json.dumps(f.timeframe)}, model: {json.dumps(f.model)} }},")
    out.append("};")
    out.append(f"export const SNAPSHOT_SINGLE_FIELDS = {json.dumps([f.base for f in singles])} as const;")
    out.append(f"export const SNAPSHOT_MULTI_FIELDS = {json.dumps(list(multis))} as const;")
    out.append("")


def emit_node_types(api: Api, node: Node, out: list[str]) -> None:
    for child in node.children.values():
        emit_node_types(api, child, out)
    if not node.path:
        return
    name = type_name(node)
    r = node.route
    members: list[str] = []
    if r is not None:
        title = f"{r.method} {r.path} — {r.summary}"
        if r.shape == "snapshot":
            emit_snapshot(api, r, out)
            members.append("  (params: SnapshotParams, options?: RequestOptions): Promise<ApiResponse<SnapshotData>>;")
            members.extend(jsdoc("The fields `snapshot()` accepts for a symbol, their timeframes and maximum depths (in `response.meta`).", 2))
            members.append("  catalog(params: { symbol: string }, options?: RequestOptions): Promise<ApiResponse<SnapshotData>>;")
        elif r.shape == "indicators":
            members.append(
                "  (params: IndicatorsParams, options?: RequestOptions): Promise<ApiResponse<IndicatorsResult | null>>;"
            )
        else:
            req = emit_params(f"{name}Params", r.params, out)
            arg = f"params: {name}Params" if req else f"params?: {name}Params"
            doc_lines = jsdoc(f"{title}\n\n{r.description}", 2)
            members.extend(doc_lines)
            members.append(f"  ({arg}, options?: RequestOptions): Promise<ApiResponse<{return_ts(r)}>>;")
            if r.paginated:
                emit_params(f"{name}IterParams", r.params, out, exclude={"limit", "before_ms", "after_id"})
                out.append(f"export type {name}IterOptions = {name}IterParams & IterOptions;")
                out.append("")
                item = f"M.{r.model}" if r.model else "unknown"
                members.extend(jsdoc(f"Every row of `{r.path}` over a period, following `next` page after page (`for await`).", 2))
                members.append(f"  iter({'params' if req else 'params?'}: {name}IterOptions, options?: RequestOptions): RowIterator<{item}>;")
    for seg, child in node.children.items():
        members.append(f"  {key(prop(seg))}: {type_name(child)}Resource;")
    out.append(f"/** `{r.path if r else '/v1/' + '/'.join(node.path)}`{' and its sub-routes' if node.children else ''}. */")
    out.append(f"export interface {name}Resource {{")
    out.extend(members)
    out.append("}")
    out.append("")


def emit_node_value(node: Node, indent: int) -> str:
    pad = " " * indent
    r = node.route
    children = ",\n".join(f"{pad}  {key(prop(seg))}: {emit_node_value(child, indent + 2)}" for seg, child in node.children.items())
    if r is None:
        return "{\n" + children + f"\n{pad}}}"
    const = "R_" + re.sub(r"\W", "_", r.ident).upper()
    if r.shape == "snapshot":
        base = f"core.snapshotResource({const})"
    elif r.shape == "indicators":
        base = f"core.indicatorsResource({const})"
    else:
        base = f"core.resource({const})"
    if not node.children:
        return base
    return f"Object.assign({base}, {{\n{children}\n{pad}}})"


def emit_resources(api: Api) -> str:
    out = [
        HEADER,
        "/** Every route of the API, as properties of the client: `/v1/funding/rate/history` is `client.funding.rate.history(...)`. */",
        "",
        "import type { ApiResponse, Core, Fields, IterOptions, RequestOptions, RouteSpec, RowIterator, TimeLike } from '../core.js';",
        "import type { IndicatorsParams, IndicatorsResult } from '../indicatorSpec.js';",
        "import type * as M from './models.js';",
        f"import type {{ {', '.join(param_literals(api))} }} from './literals.js';",
        "",
    ]
    for r in api.routes:
        const = "R_" + re.sub(r"\W", "_", r.ident).upper()
        out.append(f"const {const}: RouteSpec = {route_const(r)};")
    out.append("")
    emit_node_types(api, api.tree, out)
    out.append("export interface Resources {")
    for seg, child in api.tree.children.items():
        out.append(f"  {key(prop(seg))}: {type_name(child)}Resource;")
    out.append("}")
    out.append("")
    out.append("/** @internal */")
    out.append("export function createResources(core: Core): Resources {")
    out.append("  return {")
    for seg, child in api.tree.children.items():
        out.append(f"    {key(prop(seg))}: {emit_node_value(child, 4)} as {type_name(child)}Resource,")
    out.append("  };")
    out.append("}")
    out.append("")
    out.append("/** Every route and the SDK method that serves it. */")
    out.append("export const ROUTES: Record<string, string> = {")
    for r in api.routes:
        out.append(f"  {json.dumps(r.path)}: {json.dumps('.'.join(prop(s) for s in r.segments))},")
    out.append("};")
    out.append(f"/** `info.version` of the contract this SDK was generated from. */\nexport const API_VERSION = {json.dumps(api.version)};")
    return "\n".join(out) + "\n"


# --------------------------------------------------------------------------- indicators


def emit_indicators(api: Api) -> str:
    out = [
        HEADER,
        "/** Typed builders for `client.indicators(...)`: `ind.rsi(14)`, `ind.macd()`, `ind.bb({ period: 20, std: 2.5 })`. */",
        "",
        "import { IndicatorSpec, check } from '../indicatorSpec.js';",
        "",
    ]
    for name, spec in api.indicators.items():
        params = spec["params"]
        iface = pascal(name) + "Params"
        out.append(f"export interface {iface} {{")
        for p, d in params.items():
            bounds = f"min {d['min']}" + (f", max {d['max']}" if d.get("max") is not None else "")
            out.append(f"  /** Default {d['default']} ({bounds}){' — an integer' if d['type'] == 'int' else ''}. */")
            out.append(f"  {p}?: number;")
        out.append("  /** Name of the result in `data.indicators` (default: generated, e.g. `rsi_14`). */")
        out.append("  id?: string;")
        out.append("}")
        first = next(iter(params), None)
        outs = spec["outputs"]
        ptxt = ", ".join(f"`{p}` (default {d['default']})" for p, d in params.items()) or "no parameter"
        out.extend(jsdoc(f"`{name}` ({spec['group']}): {ptxt}. Output: {'one series' if not outs else ', '.join('`' + o + '`' for o in outs)}."))
        arg = f"params: {iface} | number = {{}}" if first else f"params: {iface} = {{}}"
        out.append(f"export function {name}({arg}): IndicatorSpec {{")
        if first:
            out.append(f"  const p: {iface} = typeof params === 'number' ? {{ {first}: params }} : params;")
        else:
            out.append("  const p = params;")
        out.append("  const values: Record<string, number> = {};")
        for p, d in params.items():
            out.append(
                f"  values[{json.dumps(p)}] = check({json.dumps(name)}, {json.dumps(p)}, p.{p} ?? {d['default']!r}, {d['min']!r}, {json.dumps(d.get('max'))}, {'true' if d['type'] == 'int' else 'false'});"
            )
        out.append(f"  return new IndicatorSpec({json.dumps(name)}, values, p.id);")
        out.append("}")
        out.append("")
    out.append("export const INDICATOR_OUTPUTS: Record<string, readonly string[] | null> = {")
    for name, spec in api.indicators.items():
        out.append(f"  {name}: {json.dumps(spec['outputs'])},")
    out.append("};")
    return "\n".join(out) + "\n"


def write(api: Api, root: Path) -> list[Path]:
    out = root / "typescript" / "src" / "generated"
    out.mkdir(parents=True, exist_ok=True)
    files = {
        "literals.ts": emit_literals(api),
        "models.ts": emit_models(api),
        "resources.ts": emit_resources(api),
        "indicators.ts": emit_indicators(api),
    }
    written = []
    for name, content in files.items():
        p = out / name
        p.write_text(content, encoding="utf-8", newline="\n")
        written.append(p)
    return written
